Definition ATAB : Z := 0x28c80.                       (* [comment removed for export] *)
Definition NATAB : Z := 18446744073709551615 - 0x28c80.   (* [comment removed for export] *)
Definition cut_pc (c : nat) : Z :=
  match c with 0%nat => 0xd7468 | 1%nat => 0xd7498 | 2%nat => 0xd74e8 | 3%nat => 0xd7504 | 4%nat => 0xd7588
             | 5%nat => 0xd760c | 6%nat => 0xd76c0 | 7%nat => 0xd7714 | _ => 0xd7828 end.
Definition cut_rank (c : nat) : Z :=
  match c with 2%nat | 8%nat => 1 | _ => 0 end.
(* [comment removed for export] *)
Definition cut_it (c : nat) (p : Z) : Z := match c with 0%nat | 6%nat => p | _ => p - 1 end.
(* [comment removed for export] *)
Definition cut_rel (c : nat) (p : Z) (w2 w3 w4 w5 w6 w7 s3x s4x : word) : Prop :=
  match c with
  | 0%nat => w2 = wz p
  | 1%nat => w3 = wz (p - 1) /\ w2 = wz p
  | 2%nat => w2 = wz (p - 1)
  | 3%nat => w2 = wz p /\ w4 = wz p /\ w3 = wz (p + 1) /\ w6 = wz (p + 1) /\ w5 = wz (p + 2) /\ w7 = wz (p + 2)
  | 4%nat => w3 = wz p /\ w6 = wz p /\ w5 = wz (p + 1) /\ w7 = wz (p + 1) /\ s3x = wz ATAB /\ s4x = wz NATAB
  | 5%nat => w2 = wz p /\ w4 = wz p /\ s3x = wz ATAB /\ s4x = wz NATAB
  | 6%nat => w2 = wz p /\ w3 = wz p /\ w4 = wz (p + 1) /\ w5 = wz (p + 1) /\ s3x = wz ATAB /\ s4x = wz NATAB
  | 7%nat => w3 = wz (p - 1)
  | _ => w4 = wz p /\ w5 = wz p /\ s3x = wz ATAB
  end.
Definition cut_side (c : nat) (p itv it0 L : Z) : Prop :=
  itv = cut_it c p /\ it0 <= cut_it c p /\ cut_it c p < L.

