Definition chx_regs (rax spv gp tp : word) (w2 w3 w4 w5 w6 w7 s3x s4x s7x s8x : word) (I L E : Z) (s9 s10 s11 : word) :=
  mkR rax spv gp tp (wz 1) (wz 32) (wz 59) (wz E) (wz ASHADOW_BASE) (wz I) (wz L) w2 w3 w4 w5
      (Z_to_bv 64 (Z.shiftr I 3 + 2147450880)) (wz 9)
      (wz 92) s3x s4x w6 w7 s7x s8x s9 s10 s11 (wz 2) (wz 61) (wz 18446744073709551615) (wz 34).

(* [comment removed for export] *)
Definition CUT_AT (c : nat) (B : Z) : Prop :=
  forall (p : Z) (w2 w3 w4 w5 w6 w7 s3x s4x s7x s8x : word) rax ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9 s10 s11
    (F : bvmap 5 word) fc (m m1 : mem) (it0 I E lo shi : Z) (bs : list byte) (itv : Z) (E0 : ecv) (g : bool) (j8 junk : list byte),
  chx_ctx m m1 sp s0v s1v s2v s3v s4v s5v s6v s7v s8v ra it0 I E lo shi bs itv E0 g j8 junk -> chx_pure sp it0 I E lo shi bs E0 ->
  cut_side c p itv it0 (it0 + Z.of_nat (length bs)) ->
  cut_rel c p w2 w3 w4 w5 w6 w7 s3x s4x ->
  2 * (it0 + Z.of_nat (length bs) - p) + cut_rank c < B ->
  evt bsegs (chx_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9 s10 s11 F fc it0 I E lo shi bs E0 m)
    (MS (chx_regs rax (Z_to_bv 64 (bv_unsigned sp + -112)) gp tp w2 w3 w4 w5 w6 w7 s3x s4x s7x s8x
                  I (it0 + Z.of_nat (length bs)) E s9 s10 s11)
        F (Z_to_bv 64 (cut_pc c)) fc None m1 (seg_rom bsegs)).

Definition CUTS (B : Z) : Prop := forall c, (c <= 8)%nat -> CUT_AT c B.

