Ltac ctx_open_core CTX PURE :=
  let CTX' := fresh "CTX'" in let PURE' := fresh "PURE'" in
  pose proof CTX as CTX'; pose proof PURE as PURE';
  destruct CTX' as (FR0 & TMP & FRhi & IT & EC & ST & WIN & MU & WM & MI & MU2 & HC & SD);
  destruct PURE' as (EOK & LO & CEIL & APP & QHI & ILO & IHI & IAL & APE & EAL & DQE & SPAL & SHI);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (aapp_bounds _ _ APP ltac:(lia)) as (PB1 & PB2 & PB3 & PB4 & PB5);
  pose proof (aapp_bounds _ 24 APE ltac:(lia)) as (EB1 & EB2 & EB3 & EB4 & _);
  pose proof aceil_facts as (AF1 & AF2 & AF3);
  pose proof (stack0_bounds _ _ _ (pside_stack0 _ _ _ _ _ SD)) as [SKB1 SKB2];
  lazymatch type of ST with stk _ _ _ (bv_unsigned ?sp + _) =>
    pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR end;
  (* [comment removed for export] *)
  clear IAL APP APE EAL SPAL AF2 AF3 PB5 EOK DQE;
  unfold chx_W, CHX_STACK, AASSIGN_STACK, AINTRIN_STACK, AG_HTTP_CAT, AAPP_HI, AIMG_TOP in *;
  unfold ErrCodeCells in EC; unfold chx_regs in *.
Ltac cut_open :=
  intros p w2 w3 w4 w5 w6 w7 s3x s4x s7x s8x rax ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9 s10 s11 F fc m m1 it0 I E lo shi bs itv E0 g j8 junk;
  intros CTX PURE SIDE REL MEAS;
  ctx_open_core CTX PURE;
  unfold cut_pc, cut_side, cut_it in SIDE |- *; unfold cut_rel, ATAB, NATAB in REL; unfold cut_rank in MEAS;
  unfold wz in *; rewrite ASHADOW_BASE_val.

