    HC : AHttpCat ?m0 ?g, SD : chx_side ?m0 ?it0 ?E ?lo ?shi _
    |- evt _ (chx_post _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ ?bs ?E0 _) _ =>
      assert (CTX : chx_ctx m0 mx sp s0v s1v s2v s3v s4v s5v s6v s7v s8v rav it0 I E lo shi bs itv E0 g j8 junk)
